  const int base_d = d0 + padding - (K - 1);
  const int base_h = h0 + padding - (K - 1);
  const int base_w = w0 + padding - (K - 1);
  // Stage weights (ic, oc0..oc0+OC_TILE) and the haloed input tile for
  // input channel ic into shared-memory buffer `buf` (zero-filled outside).
  // Uses cp.async so global->shared transfers bypass registers and overlap
  // with the accumulation from the other buffer.
  auto stage_tile = [&](int ic, int buf) {
    Tensor sW = make_sW(buf);
    #pragma unroll
    for (int o = 0; o < OC_TILE; ++o) {
      const int oc = oc0 + o;
      const bool ovalid = (oc < C_out);
      for (int k = tid; k < K3; k += THREADS) {
        const float* src = Wp;
        if (ovalid) {
          int kd = k / K2;
          int r  = k - kd * K2;
          int kh = r / K;
          int kw = r - kh * K;
          src = &mW(ic, oc, kd, kh, kw);
        }
        cp_async4(&sW(o, k), src, ovalid);
      }
    }
    Tensor sX = make_sX(buf);
    for (int idx = tid; idx < SD * SH * SW; idx += THREADS) {
      int ld  = idx / (SH * SW);
      int rem = idx - ld * (SH * SW);
      int lh  = rem / SW;
      int lw  = rem - lh * SW;
      int gd = base_d + ld;
      int gh = base_h + lh;
      int gw = base_w + lw;
      const bool inb = ((unsigned)gd < (unsigned)D &&
                        (unsigned)gh < (unsigned)H &&
                        (unsigned)gw < (unsigned)W);
      const float* src = inb ? &mX(ic, gd, gh, gw) : Xp;
      cp_async4(&sX(ld, lh, lw), src, inb);
    }
  };
  // Pipelined main loop: prefetch the next input-channel tile into the
  // idle buffer while accumulating from the current one (one barrier/step).
  stage_tile(0, 0);
  cp_async_commit_group();
  for (int ic = 0; ic < C_in; ++ic) {
    const int cur = ic & 1;
    if (ic + 1 < C_in) {
      stage_tile(ic + 1, cur ^ 1);
    }
    // Commit this stage as a cp.async group, then wait until the group
    // holding the current buffer has landed (at most one group in flight).
    cp_async_commit_group();
    cp_async_wait_group<1>();
    __syncthreads();
    Tensor sX = make_sX(cur);
    Tensor sW = make_sW(cur);
    // Accumulate over the K^3 taps from shared memory. For each tap, load the
    // OC_TILE weights once and reuse them for the RB_H x RB_W register-blocked
    // outputs, doubling the FMAs issued per shared-memory load.
    #pragma unroll
    for (int kd = 0; kd < K; ++kd) {
      const int sxd = td + (K - 1 - kd);
      #pragma unroll
      for (int kh = 0; kh < K; ++kh) {
        const int sxh = th + (K - 1 - kh);
        #pragma unroll
        for (int kw = 0; kw < K; ++kw) {
          const int sxw0 = tw + (K - 1 - kw);
          float xv[RB_H][RB_W];
          #pragma unroll
          for (int hh = 0; hh < RB_H; ++hh) {
            #pragma unroll
            for (int r = 0; r < RB_W; ++r) {
              xv[hh][r] = sX(sxd, sxh + hh * THT, sxw0 + r * TWT);
            }
          }
          const int kk = (kd * K + kh) * K + kw;
          #pragma unroll
          for (int o = 0; o < OC_TILE; ++o) {
            const float wv = sW(o, kk);
            #pragma unroll
            for (int hh = 0; hh < RB_H; ++hh) {
              #pragma unroll
              for (int r = 0; r < RB_W; ++r) {
                acc[o][hh][r] = fmaf(xv[hh][r], wv, acc[o][hh][r]);
              }
            }
          }
        }
      }
    }
    __syncthreads();
  }
  // Epilogue: guarded stores for the RB_H x RB_W outputs owned by this thread
  const int gd = d0 + td;
  if (gd < Dout) {
    #pragma unroll
    for (int hh = 0; hh < RB_H; ++hh) {
      const int gh = h0 + th + hh * THT;
      if (gh < Hout) {
        #pragma unroll
        for (int r = 0; r < RB_W; ++r) {
          const int gw = w0 + tw + r * TWT;
          if (gw < Wout) {
            #pragma unroll
            for (int o = 0; o < OC_TILE; ++o) {
              const int oc = oc0 + o;
              if (oc < C_out) {
                mY(oc, gd, gh, gw) = acc[o][hh][r];
              }
            }
          }
        }
      }
    }
  }
}
template <int K>
static void launch_conv_transpose3d_s1(
    const float* x, const float* w, const float* b, float* y,
    int N, int C_in, int C_out,
    int D, int H, int W,
    int Dout, int Hout, int Wout,
    int padding, cudaStream_t stream)
{
  constexpr int TW = 16;
  constexpr int TH = (K <= 5 ? 16 : 8);
  constexpr int TD = (K <= 5 ? 4 : 8);
  constexpr int OC_TILE = (K <= 5 ? 16 : (K == 6 ? 8 : 4));
  const unsigned tiles =
      (unsigned)((Dout + TD - 1) / TD) *
      (unsigned)((Hout + TH - 1) / TH) *
      (unsigned)((Wout + TW - 1) / TW);
  dim3 grid(tiles, (unsigned)((C_out + OC_TILE - 1) / OC_TILE), (unsigned)N);
  dim3 block(128);  // THREADS = TD * THT * TWT == 128 for all K (RB_H=2 register blocking)
  conv_transpose3d_s1_kernel<K><<<grid, block, 0, stream>>>(
      x, w, b, y, C_in, C_out, D, H, W, Dout, Hout, Wout, padding);
