    case 3: launch_conv_transpose3d_s1<3>(xp, wp, b_ptr, yp, (int)N, (int)C_in, (int)C_out, (int)D, (int)H, (int)W, (int)Dout, (int)Hout, (int)Wout, (int)padding, stream); break;
    case 4: launch_conv_transpose3d_s1<4>(xp, wp, b_ptr, yp, (int)N, (int)C_in, (int)C_out, (int)D, (int)H, (int)W, (int)Dout, (int)Hout, (int)Wout, (int)padding, stream); break;
    case 5: launch_conv_transpose3d_s1<5>(xp, wp, b_ptr, yp, (int)N, (int)C_in, (int)C_out, (int)D, (int)H, (int)W, (int)Dout, (int)Hout, (int)Wout, (int)padding, stream); break;
    case 6: launch_conv_transpose3d_s1<6>(xp, wp, b_ptr, yp, (int)N, (int)C_in, (int)C_out, (int)D, (int)H, (int)W, (int)Dout, (int)Hout, (int)Wout, (int)padding, stream); break;
    case 7: launch_conv_transpose3d_s1<7>(xp, wp, b_ptr, yp, (int)N, (int)C_in, (int)C_out, (int)D, (int)H, (int)W, (int)Dout, (int)Hout, (int)Wout, (int)padding, stream); break;
    default:
