  float acc[OC_TILE][RB_H][RB_W];
  #pragma unroll
  for (int o = 0; o < OC_TILE; ++o) {
    const float bv = (Bp != nullptr && (oc0 + o) < C_out) ? Bp[oc0 + o] : 0.0f;
    #pragma unroll
    for (int hh = 0; hh < RB_H; ++hh) {
